    /// <summary>
    /// Check if substitutions (extended functionality) should be applied to this line.
    /// </summary>
    /// <returns>True if subs enabled</returns>
    public boolean metSubstitutionsActive()
    {
        boolean ret = true;

        if(!this.salesTable().custTable_CustAccount().METSalesItemSubstitutionEnabled)
            ret = false;

        return ret;
    }

/// <summary>
/// To get grossWeight for the SalesLine Item.
/// </summary>
/// <returns>GrossWeight of salesLine Item</returns>
public display ItemGrossWeight grossWeight()
{
    InventTable     inventTable = InventTable::find(this.ItemId);
    return inventTable.NetWeight + inventTable.TaraWeight;
}

/// <summary>
/// To get unitVolume for the SalesLine Item.
/// </summary>
/// <returns>unitVolume of salesLine Item</returns>
public display ItemVolume unitVolume()
{
    return InventTable::find(this.ItemId).UnitVolume;
}

/// <summary>
/// To calculate and display the number of cases for the sales order line quantity.
/// </summary>
/// <returns>unitVolume of salesLine Item</returns>
public display int cases()
{
    return roundUp(UnitOfMeasureConversion::findByConversion(UnitOfMeasure::findBySymbol(this.SalesUnit).RecId,UnitOfMeasure::findBySymbol('Case').RecId,EcoResProduct::findByProductNumber(this.ItemId).RecId).Factor,0);
}
